apiVersion: networking.istio.io/v1
kind: DestinationRule
metadata: {name: frontend, namespace: shop}
spec:
  host: frontend
  trafficPolicy:
    loadBalancer:
      consistentHash:
        httpCookie: {name: session, ttl: 0s}
        ringHash: {minimumRingSize: 1024}
    outlierDetection: {consecutive5xxErrors: 3, interval: 10s, baseEjectionTime: 30s}
  subsets:
    - {name: stable, labels: {version: v1}}
    - {name: canary, labels: {version: v2}}

apiVersion: networking.istio.io/v1
kind: VirtualService
metadata: {name: frontend, namespace: shop}
spec:
  hosts: [frontend]
  http:
    - route:
        - {destination: {host: frontend, subset: stable}, weight: 90}
        - {destination: {host: frontend, subset: canary}, weight: 10}
      timeout: 3s
      retries: {attempts: 2, perTryTimeout: 1s, retryOn: "5xx,connect-failure"}
